// Overlays the hand-written declarations in src/ on top of the declarations
// generated by `tsc -p tsconfig.build.json` (see issue #135).
//
// Most of the core is plain JavaScript with a sibling hand-written .d.ts
// (src/channel.js + src/channel.d.ts, …). tsc infers declarations from the
// .js, which is far weaker than the hand-written pair, so the hand-written
// file wins where one exists. Inside dist/types there is no .js or .ts to
// shadow it, so `export * from "./channel.js"` resolves to channel.d.ts.
import {mkdir, copyFile, readdir} from "node:fs/promises";
import {dirname, join, relative, sep} from "node:path";
import {fileURLToPath} from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "src");
const target = join(root, "dist", "types");

// src/react/index.d.ts is a stub that re-exports "./index.js" (the sibling
// index.tsx). Copying it would clobber the real generated entry point with a
// self-referential export.
const skip = new Set([join("react", "index.d.ts")]);

async function* declarations(dir) {
  for (const entry of await readdir(dir, {withFileTypes: true})) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* declarations(path);
    else if (entry.name.endsWith(".d.ts")) yield path;
  }
}

let count = 0;
for await (const path of declarations(source)) {
  const name = relative(source, path);
  if (skip.has(name)) continue;
  const destination = join(target, name);
  await mkdir(dirname(destination), {recursive: true});
  await copyFile(path, destination);
  ++count;
}

console.log(`copied ${count} hand-written declaration${count === 1 ? "" : "s"} into dist${sep}types`);
